UPDATE menu_items SET description = 'The music has faded, the lights have come up, and the night finally catches up with you. Inspired by the album “Music, Fashion, Film”, it explores performance as identity. Every role we play leaves behind traces of the person beneath it. Rich espresso and spiced rum carry the warmth of the dance floor, while herbal liqueur and Bianco vermouth soften into bittersweet reflection. A touch of soy sauce adds unexpected depth, and a whisper of rose lingers like perfume left on a jacket long after sunrise. Bold, velvety, and quietly nostalgic.', ingredients = '["Dark Spiced Rum","Heering Cherry Liqueur","Espresso","Martini Bianco Vermouth","Vanilla Syrup","Soy Sauce","Rose Water","Egg White"]' WHERE code = 'ken-224';
